#!/usr/bin/env python3
"""angle-grinder (agrind) - slice and dice log files on the command line"""

import sys
import os
import re
import json
import math
import argparse
from datetime import datetime, timezone, timedelta
from collections import defaultdict, OrderedDict
from typing import Optional, List, Dict, Any, Tuple

# ============================================================================
# Data Types
# ============================================================================

class Value:
    """Represents a typed value in agrind"""
    def __init__(self, val):
        self.val = val

    def __repr__(self):
        return f"Value({self.val!r})"

    @staticmethod
    def format(val) -> str:
        """Format a value for display"""
        if val is None:
            return "None"
        if isinstance(val, bool):
            return "true" if val else "false"
        if isinstance(val, int):
            return str(val)
        if isinstance(val, float):
            if val == int(val) and not math.isnan(val) and not math.isinf(val):
                return str(int(val))
            else:
                return f"{val:.2f}"
        if isinstance(val, list):
            items = ", ".join(Value.format(v) for v in val)
            return f"[{items}]"
        if isinstance(val, dict):
            items = ", ".join(f"{k}:{Value.format(v)}" for k, v in sorted(val.items()))
            return f"{{{items}}}"
        return str(val)

    @staticmethod
    def to_num(val) -> Optional[float]:
        """Try to convert to number"""
        if isinstance(val, (int, float)) and not isinstance(val, bool):
            return float(val)
        if isinstance(val, str):
            try:
                return float(val)
            except ValueError:
                return None
        return None

Row = Dict[str, Any]  # A row is a dict of field -> value

# ============================================================================
# Query Parser
# ============================================================================

class ParseError(Exception):
    def __init__(self, message, query=None, pos=None, length=None):
        self.message = message
        self.query = query
        self.pos = pos
        self.length = length
        super().__init__(message)

    def format_error(self, query=None):
        q = query or self.query or ""
        lines = []
        lines.append(f"error: {self.message}")
        if q and self.pos is not None:
            lines.append("  |")
            lines.append(f"1 | {q}")
            pos = self.pos
            length = self.length or 1
            lines.append(f"  | {' ' * pos}{'^' * length}")
            lines.append("  |")
        return "\n".join(lines)


class Token:
    def __init__(self, type_, value, pos):
        self.type = type_
        self.value = value
        self.pos = pos

    def __repr__(self):
        return f"Token({self.type}, {self.value!r}, {self.pos})"


class Lexer:
    """Simple lexer for agrind query language"""

    KEYWORDS = {'and', 'or', 'not', 'by', 'as', 'from', 'on', 'asc', 'desc', 
                'only', 'except', 'drop', 'keep', 'json', 'logfmt', 'split',
                'parse', 'fields', 'limit', 'where', 'timeslice', 'total',
                'count', 'sum', 'min', 'max', 'average', 'sort', 'avg',
                'count_distinct'}

    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.tokens = []
        self._tokenize()

    def _tokenize(self):
        text = self.text
        i = 0
        while i < len(text):
            # Skip whitespace
            if text[i].isspace():
                i += 1
                continue

            # Pipe
            if text[i] == '|':
                self.tokens.append(Token('PIPE', '|', i))
                i += 1
                continue

            # Comma
            if text[i] == ',':
                self.tokens.append(Token('COMMA', ',', i))
                i += 1
                continue

            # Parentheses
            if text[i] == '(':
                self.tokens.append(Token('LPAREN', '(', i))
                i += 1
                continue
            if text[i] == ')':
                self.tokens.append(Token('RPAREN', ')', i))
                i += 1
                continue

            # Bracket field names [...]
            if text[i] == '[' and i+1 < len(text) and text[i+1] == '"':
                # ["field name"]
                end = text.find('"]', i+2)
                if end == -1:
                    raise ParseError("Unterminated field name", text, i)
                field = text[i+2:end]
                self.tokens.append(Token('FIELD', field, i))
                i = end + 2
                continue

            # Array index [N]
            if text[i] == '[':
                # Could be array index
                j = i + 1
                while j < len(text) and (text[j].isdigit() or text[j] == '-'):
                    j += 1
                if j < len(text) and text[j] == ']' and j > i + 1:
                    idx = text[i+1:j]
                    self.tokens.append(Token('BRACKETIDX', idx, i))
                    i = j + 1
                    continue
                self.tokens.append(Token('LBRACKET', '[', i))
                i += 1
                continue

            if text[i] == ']':
                self.tokens.append(Token('RBRACKET', ']', i))
                i += 1
                continue

            # Operators
            if text[i:i+2] in ('==', '!=', '>=', '<='):
                self.tokens.append(Token('OP', text[i:i+2], i))
                i += 2
                continue
            if text[i] in ('<', '>'):
                self.tokens.append(Token('OP', text[i], i))
                i += 1
                continue

            # Plus/minus for field operators
            if text[i] == '+':
                self.tokens.append(Token('PLUS', '+', i))
                i += 1
                continue
            if text[i] == '-':
                # Could be minus or negative number
                self.tokens.append(Token('MINUS', '-', i))
                i += 1
                continue

            # Multiply/divide for expressions
            if text[i] == '*' and (i == 0 or not text[i-1].isalnum()):
                # Check if it's a wildcard filter vs multiply
                self.tokens.append(Token('STAR', '*', i))
                i += 1
                continue

            if text[i] == '/':
                self.tokens.append(Token('DIV', '/', i))
                i += 1
                continue

            if text[i] == '%':
                self.tokens.append(Token('MOD', '%', i))
                i += 1
                continue

            # Dot  
            if text[i] == '.':
                self.tokens.append(Token('DOT', '.', i))
                i += 1
                continue

            # Quoted string
            if text[i] == '"':
                j = i + 1
                s = []
                while j < len(text) and text[j] != '"':
                    if text[j] == '\\' and j+1 < len(text):
                        s.append(text[j+1])
                        j += 2
                    else:
                        s.append(text[j])
                        j += 1
                if j >= len(text):
                    raise ParseError("Unterminated string", text, i)
                self.tokens.append(Token('STRING', ''.join(s), i))
                i = j + 1
                continue

            # Number
            if text[i].isdigit():
                j = i
                while j < len(text) and (text[j].isdigit() or text[j] == '.'):
                    j += 1
                num_str = text[i:j]
                try:
                    if '.' in num_str:
                        num = float(num_str)
                    else:
                        num = int(num_str)
                    self.tokens.append(Token('NUMBER', num, i))
                except ValueError:
                    self.tokens.append(Token('IDENT', num_str, i))
                i = j
                continue

            # Identifier
            if text[i].isalpha() or text[i] == '_':
                j = i
                while j < len(text) and (text[j].isalnum() or text[j] in '_'):
                    j += 1
                word = text[i:j]
                # Check for p/pct/percentile prefix
                if word.lower() in self.KEYWORDS:
                    self.tokens.append(Token('KEYWORD', word.lower(), i))
                else:
                    self.tokens.append(Token('IDENT', word, i))
                i = j
                continue

            # Unknown character
            raise ParseError(f"Unexpected character: {text[i]!r}", text, i)

        self.tokens.append(Token('EOF', '', len(text)))


class QueryParser:
    """Parser for agrind query language"""

    def __init__(self, text, aliases=None):
        self.text = text
        self.aliases = aliases or {}
        self.lexer = Lexer(text)
        self.tokens = self.lexer.tokens
        self.pos = 0

    def current(self):
        return self.tokens[self.pos]

    def peek(self, offset=1):
        idx = self.pos + offset
        if idx < len(self.tokens):
            return self.tokens[idx]
        return self.tokens[-1]

    def consume(self, type_=None, value=None):
        tok = self.tokens[self.pos]
        if type_ and tok.type != type_:
            raise ParseError(f"Expected {type_}, got {tok.type!r} ({tok.value!r})", 
                           self.text, tok.pos, len(tok.value) if tok.value else 1)
        if value and tok.value != value:
            raise ParseError(f"Expected {value!r}, got {tok.value!r}",
                           self.text, tok.pos, len(tok.value) if tok.value else 1)
        self.pos += 1
        return tok

    def match(self, type_=None, value=None):
        tok = self.tokens[self.pos]
        if type_ and tok.type != type_:
            return False
        if value and tok.value != value:
            return False
        return True

    def parse(self):
        """Parse a full query: filters | op1 | op2 | ..."""
        # Parse filters
        filters = self.parse_filters()

        operators = []
        while self.match('PIPE'):
            self.consume('PIPE')
            op = self.parse_operator()
            operators.append(op)

        if not self.match('EOF'):
            tok = self.current()
            raise ParseError(f"Unexpected token: {tok.value!r}", self.text, tok.pos, len(str(tok.value)))

        return {'filters': filters, 'operators': operators}

    def parse_filters(self):
        """Parse filter expression"""
        return self.parse_or_filter()

    def parse_or_filter(self):
        left = self.parse_and_filter()
        while self.match('KEYWORD', 'or') or (self.match('IDENT') and self.current().value.lower() == 'or'):
            self.consume()
            right = self.parse_and_filter()
            left = ('or', left, right)
        return left

    def parse_and_filter(self):
        left = self.parse_not_filter()
        while self.match('KEYWORD', 'and') or (self.match('IDENT') and self.current().value.lower() == 'and'):
            self.consume()
            right = self.parse_not_filter()
            left = ('and', left, right)
        return left

    def parse_not_filter(self):
        if (self.match('KEYWORD', 'not') or 
            (self.match('IDENT') and self.current().value.lower() == 'not')):
            self.consume()
            f = self.parse_primary_filter()
            return ('not', f)
        return self.parse_primary_filter()

    def parse_primary_filter(self):
        tok = self.current()

        # Parenthesized group
        if self.match('LPAREN'):
            self.consume('LPAREN')
            f = self.parse_filters()
            self.consume('RPAREN')
            return f

        # Star = match all
        if self.match('STAR'):
            self.consume('STAR')
            return ('star',)

        # Quoted string - case sensitive, no wildcards
        if self.match('STRING'):
            tok = self.consume('STRING')
            return ('exact', tok.value)

        # Unquoted filter (case insensitive, may include *)
        # Collect until | or AND/OR/NOT or EOF or )
        # An unquoted filter can include * wildcards
        if self.match('IDENT') or self.match('KEYWORD') or self.match('NUMBER'):
            # Build the filter string
            parts = []
            start_pos = self.current().pos
            while True:
                tok = self.current()
                if tok.type in ('PIPE', 'EOF', 'RPAREN'):
                    break
                # Check for AND/OR/NOT
                if tok.type in ('KEYWORD', 'IDENT') and tok.value.lower() in ('and', 'or', 'not'):
                    break
                if tok.type == 'STAR':
                    parts.append('*')
                    self.consume()
                elif tok.type in ('IDENT', 'KEYWORD', 'NUMBER', 'STRING'):
                    parts.append(str(tok.value))
                    self.consume()
                else:
                    break

            if parts:
                filter_str = ''.join(parts)
                return ('glob', filter_str)

        raise ParseError(f"Expected a filter", self.text, tok.pos, len(str(tok.value)) if tok.value else 1)

    def parse_operator(self):
        """Parse an operator (json, logfmt, parse, count, etc.)"""
