def parse_json_value(val) -> Any:
    """Convert JSON value to our internal representation"""
    if val is None:
        return None
    if isinstance(val, bool):
        return val
    if isinstance(val, (int, float)):
        return val
    if isinstance(val, str):
        return val
    if isinstance(val, list):
        return val
    if isinstance(val, dict):
        return val
    return val


def get_field(row: Row, field: str) -> Any:
    """Get a field value, supporting dotted paths and array indices"""
    if field in row:
        return row[field]

    # Try dotted path
    parts = _split_field_path(field)
    if len(parts) <= 1:
        return None

    val = row.get(parts[0])
    for part in parts[1:]:
        if val is None:
            return None
        if isinstance(part, int):
            if isinstance(val, list):
                try:
                    val = val[part]
                except IndexError:
                    return None
            else:
                return None
        else:
            if isinstance(val, dict):
                val = val.get(part)
            else:
                return None
    return val


def _split_field_path(field: str) -> List:
    """Split a field path like 'a.b[0].c' into ['a', 'b', 0, 'c']"""
    parts = []
    current = ''
    i = 0
    while i < len(field):
        if field[i] == '.':
            if current:
                parts.append(current)
            current = ''
            i += 1
        elif field[i] == '[':
            if current:
                parts.append(current)
            current = ''
            j = i + 1
            while j < len(field) and field[j] != ']':
                j += 1
            idx_str = field[i+1:j]
            parts.append(int(idx_str))
            i = j + 1
        else:
            current += field[i]
            i += 1
    if current:
        parts.append(current)
    return parts


def set_field(row: Row, field: str, value: Any):
    """Set a field value"""
    row[field] = value


def apply_filter(row_str: str, row: Optional[Row], filter_expr) -> bool:
    """Apply a filter to a row string"""
    if filter_expr is None:
        return True

    kind = filter_expr[0]

    if kind == 'star':
        return True

    if kind == 'exact':
        # Case sensitive match
        return filter_expr[1] in row_str

    if kind == 'glob':
        pattern = filter_expr[1]
        return glob_match(pattern, row_str, case_sensitive=False)

    if kind == 'and':
        return apply_filter(row_str, row, filter_expr[1]) and apply_filter(row_str, row, filter_expr[2])

    if kind == 'or':
        return apply_filter(row_str, row, filter_expr[1]) or apply_filter(row_str, row, filter_expr[2])

    if kind == 'not':
        return not apply_filter(row_str, row, filter_expr[1])

    return True


def glob_match(pattern: str, text: str, case_sensitive: bool = True) -> bool:
    """Match text against a glob pattern (* is wildcard)"""
    if not case_sensitive:
        pattern = pattern.lower()
        text = text.lower()

    # Convert glob to regex
    parts = pattern.split('*')
    if len(parts) == 1:
        return pattern in text

    # Has wildcards - match as substring with wildcards
    regex = '.*'.join(re.escape(p) for p in parts)
    return bool(re.search(regex, text))


def parse_logfmt(s: str) -> Dict[str, str]:
    """Parse logfmt string into key-value pairs"""
    result = {}
    # logfmt format: key=value key="quoted value" key=
    pattern = re.compile(r'(\w+)=(?:"([^"]*)"|((?:[^\s"])*))|\s*')
    for m in pattern.finditer(s):
        if m.group(1):
            key = m.group(1)
            val = m.group(2) if m.group(2) is not None else m.group(3)
            result[key] = val
    return result


def format_value(val) -> str:
    """Format value for display"""
    return Value.format(val)


def format_field_name(name: str) -> str:
    """Format a field name for display in table"""
    return name


