class GroupKey:
    """A hashable group key"""
    def __init__(self, fields: List[str], values: tuple):
        self.fields = fields
        self.values = values

    def __hash__(self):
        return hash(self.values)

    def __eq__(self, other):
        return self.values == other.values


class CountAgg:
    def __init__(self, field=None, alias=None, by_fields=None):
        self.field = field
        self.alias = alias or '_count'
        self.by_fields = by_fields or []
        self.counts = defaultdict(int)
        self.group_order = []
        self.seen_groups = set()

    def process(self, row: Row):
        key = tuple(str(get_field(row, f)) for f in self.by_fields)
        if key not in self.seen_groups:
            self.seen_groups.add(key)
            self.group_order.append(key)
        self.counts[key] += 1

    def result(self) -> List[Row]:
        rows = []
        for key in self.group_order:
            row = {}
            for i, f in enumerate(self.by_fields):
                # Use the actual value from first occurrence
                row[f] = key[i] if key[i] != 'None' else None
                # Actually we need to track actual values...
            row[self.alias] = self.counts[key]
            rows.append(row)
        return rows


class SumAgg:
    def __init__(self, field, alias=None, by_fields=None):
        self.field = field
        self.alias = alias or '_sum'
        self.by_fields = by_fields or []
        self.sums = defaultdict(float)
        self.group_order = []
        self.seen_groups = set()
        self.group_vals = {}

