    def _get_key(self, row):
        return tuple(str(get_field(row, f)) for f in self.by_fields)

    def _get_group_vals(self, row):
        return {f: get_field(row, f) for f in self.by_fields}

    def result(self) -> List[Row]:
        rows = []
        for key in self.group_order:
            row = dict(self.group_vals[key])
            s = self.sums[key]
            row[self.alias] = int(s) if s == int(s) else s
            rows.append(row)
        return rows


