class Value:
    """Represents a typed value in agrind"""
    def __init__(self, val):
        self.val = val

    def __repr__(self):
        return f"Value({self.val!r})"

    @staticmethod
    def format(val) -> str:
        """Format a value for display"""
        if val is None:
            return "None"
        if isinstance(val, bool):
            return "true" if val else "false"
        if isinstance(val, int):
