class ParseError(Exception):
    def __init__(self, message, query=None, pos=None, length=None):
        self.message = message
        self.query = query
        self.pos = pos
        self.length = length
        super().__init__(message)

    def format_error(self, query=None):
        q = query or self.query or ""
        lines = []
        lines.append(f"error: {self.message}")
        if q and self.pos is not None:
            lines.append("  |")
            lines.append(f"1 | {q}")
            pos = self.pos
            length = self.length or 1
            lines.append(f"  | {' ' * pos}{'^' * length}")
            lines.append("  |")
        return "\n".join(lines)


class Token:
    def __init__(self, type_, value, pos):
        self.type = type_
        self.value = value
        self.pos = pos

    def __repr__(self):
        return f"Token({self.type}, {self.value!r}, {self.pos})"


class Lexer:
    """Simple lexer for agrind query language"""

    KEYWORDS = {'and', 'or', 'not', 'by', 'as', 'from', 'on', 'asc', 'desc', 
                'only', 'except', 'drop', 'keep', 'json', 'logfmt', 'split',
                'parse', 'fields', 'limit', 'where', 'timeslice', 'total',
                'count', 'sum', 'min', 'max', 'average', 'sort', 'avg',
                'count_distinct'}

    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.tokens = []
        self._tokenize()

    def _tokenize(self):
        text = self.text
        i = 0
        while i < len(text):
            # Skip whitespace
            if text[i].isspace():
                i += 1
                continue

            # Pipe
            if text[i] == '|':
                self.tokens.append(Token('PIPE', '|', i))
                i += 1
                continue

            # Comma
            if text[i] == ',':
                self.tokens.append(Token('COMMA', ',', i))
                i += 1
                continue

            # Parentheses
            if text[i] == '(':
                self.tokens.append(Token('LPAREN', '(', i))
                i += 1
                continue
            if text[i] == ')':
                self.tokens.append(Token('RPAREN', ')', i))
                i += 1
                continue

            # Bracket field names [...]
            if text[i] == '[' and i+1 < len(text) and text[i+1] == '"':
                # ["field name"]
                end = text.find('"]', i+2)
                if end == -1:
                    raise ParseError("Unterminated field name", text, i)
                field = text[i+2:end]
                self.tokens.append(Token('FIELD', field, i))
                i = end + 2
                continue

            # Array index [N]
            if text[i] == '[':
                # Could be array index
                j = i + 1
                while j < len(text) and (text[j].isdigit() or text[j] == '-'):
                    j += 1
                if j < len(text) and text[j] == ']' and j > i + 1:
                    idx = text[i+1:j]
                    self.tokens.append(Token('BRACKETIDX', idx, i))
                    i = j + 1
                    continue
                self.tokens.append(Token('LBRACKET', '[', i))
                i += 1
                continue

            if text[i] == ']':
                self.tokens.append(Token('RBRACKET', ']', i))
                i += 1
                continue

            # Operators
            if text[i:i+2] in ('==', '!=', '>=', '<='):
                self.tokens.append(Token('OP', text[i:i+2], i))
                i += 2
                continue
            if text[i] in ('<', '>'):
                self.tokens.append(Token('OP', text[i], i))
                i += 1
                continue

            # Plus/minus for field operators
            if text[i] == '+':
                self.tokens.append(Token('PLUS', '+', i))
                i += 1
                continue
            if text[i] == '-':
                # Could be minus or negative number
                self.tokens.append(Token('MINUS', '-', i))
                i += 1
                continue

            # Multiply/divide for expressions
            if text[i] == '*' and (i == 0 or not text[i-1].isalnum()):
                # Check if it's a wildcard filter vs multiply
                self.tokens.append(Token('STAR', '*', i))
                i += 1
                continue

            if text[i] == '/':
                self.tokens.append(Token('DIV', '/', i))
                i += 1
                continue

            if text[i] == '%':
                self.tokens.append(Token('MOD', '%', i))
                i += 1
                continue

            # Dot  
            if text[i] == '.':
                self.tokens.append(Token('DOT', '.', i))
                i += 1
                continue

            # Quoted string
            if text[i] == '"':
                j = i + 1
                s = []
                while j < len(text) and text[j] != '"':
                    if text[j] == '\\' and j+1 < len(text):
                        s.append(text[j+1])
                        j += 2
                    else:
                        s.append(text[j])
                        j += 1
                if j >= len(text):
                    raise ParseError("Unterminated string", text, i)
                self.tokens.append(Token('STRING', ''.join(s), i))
                i = j + 1
                continue

            # Number
            if text[i].isdigit():
                j = i
                while j < len(text) and (text[j].isdigit() or text[j] == '.'):
                    j += 1
                num_str = text[i:j]
                try:
                    if '.' in num_str:
                        num = float(num_str)
                    else:
                        num = int(num_str)
                    self.tokens.append(Token('NUMBER', num, i))
                except ValueError:
                    self.tokens.append(Token('IDENT', num_str, i))
                i = j
                continue

            # Identifier
            if text[i].isalpha() or text[i] == '_':
                j = i
                while j < len(text) and (text[j].isalnum() or text[j] in '_'):
                    j += 1
                word = text[i:j]
                # Check for p/pct/percentile prefix
                if word.lower() in self.KEYWORDS:
                    self.tokens.append(Token('KEYWORD', word.lower(), i))
                else:
                    self.tokens.append(Token('IDENT', word, i))
                i = j
                continue

            # Unknown character
            raise ParseError(f"Unexpected character: {text[i]!r}", text, i)

        self.tokens.append(Token('EOF', '', len(text)))


class QueryParser:
    """Parser for agrind query language"""

    def __init__(self, text, aliases=None):
        self.text = text
        self.aliases = aliases or {}
        self.lexer = Lexer(text)
        self.tokens = self.lexer.tokens
        self.pos = 0

    def current(self):
        return self.tokens[self.pos]

    def peek(self, offset=1):
        idx = self.pos + offset
        if idx < len(self.tokens):
            return self.tokens[idx]
        return self.tokens[-1]

    def consume(self, type_=None, value=None):
        tok = self.tokens[self.pos]
        if type_ and tok.type != type_:
            raise ParseError(f"Expected {type_}, got {tok.type!r} ({tok.value!r})", 
                           self.text, tok.pos, len(tok.value) if tok.value else 1)
        if value and tok.value != value:
            raise ParseError(f"Expected {value!r}, got {tok.value!r}",
                           self.text, tok.pos, len(tok.value) if tok.value else 1)
        self.pos += 1
        return tok

    def match(self, type_=None, value=None):
        tok = self.tokens[self.pos]
        if type_ and tok.type != type_:
            return False
        if value and tok.value != value:
            return False
        return True

    def parse(self):
        """Parse a full query: filters | op1 | op2 | ..."""
        # Parse filters
        filters = self.parse_filters()

        operators = []
        while self.match('PIPE'):
            self.consume('PIPE')
            op = self.parse_operator()
            operators.append(op)

        if not self.match('EOF'):
            tok = self.current()
            raise ParseError(f"Unexpected token: {tok.value!r}", self.text, tok.pos, len(str(tok.value)))

        return {'filters': filters, 'operators': operators}

    def parse_filters(self):
        """Parse filter expression"""
        return self.parse_or_filter()

    def parse_or_filter(self):
        left = self.parse_and_filter()
        while self.match('KEYWORD', 'or') or (self.match('IDENT') and self.current().value.lower() == 'or'):
            self.consume()
            right = self.parse_and_filter()
            left = ('or', left, right)
        return left

    def parse_and_filter(self):
        left = self.parse_not_filter()
        while self.match('KEYWORD', 'and') or (self.match('IDENT') and self.current().value.lower() == 'and'):
            self.consume()
            right = self.parse_not_filter()
            left = ('and', left, right)
        return left

    def parse_not_filter(self):
        if (self.match('KEYWORD', 'not') or 
            (self.match('IDENT') and self.current().value.lower() == 'not')):
            self.consume()
            f = self.parse_primary_filter()
            return ('not', f)
        return self.parse_primary_filter()

    def parse_primary_filter(self):
        tok = self.current()

        # Parenthesized group
        if self.match('LPAREN'):
            self.consume('LPAREN')
            f = self.parse_filters()
            self.consume('RPAREN')
            return f

        # Star = match all
        if self.match('STAR'):
            self.consume('STAR')
            return ('star',)

        # Quoted string - case sensitive, no wildcards
        if self.match('STRING'):
            tok = self.consume('STRING')
            return ('exact', tok.value)

        # Unquoted filter (case insensitive, may include *)
        # Collect until | or AND/OR/NOT or EOF or )
        # An unquoted filter can include * wildcards
        if self.match('IDENT') or self.match('KEYWORD') or self.match('NUMBER'):
            # Build the filter string
            parts = []
            start_pos = self.current().pos
            while True:
                tok = self.current()
                if tok.type in ('PIPE', 'EOF', 'RPAREN'):
                    break
                # Check for AND/OR/NOT
                if tok.type in ('KEYWORD', 'IDENT') and tok.value.lower() in ('and', 'or', 'not'):
                    break
                if tok.type == 'STAR':
                    parts.append('*')
                    self.consume()
                elif tok.type in ('IDENT', 'KEYWORD', 'NUMBER', 'STRING'):
                    parts.append(str(tok.value))
                    self.consume()
                else:
                    break

            if parts:
                filter_str = ''.join(parts)
                return ('glob', filter_str)

        raise ParseError(f"Expected a filter", self.text, tok.pos, len(str(tok.value)) if tok.value else 1)

    def parse_operator(self):
        """Parse an operator (json, logfmt, parse, count, etc.)"""
        tok = self.current()

        # Get operator name
        if not (self.match('IDENT') or self.match('KEYWORD') or self.match('NUMBER')):
            raise ParseError("Expected an operator", self.text, tok.pos, len(str(tok.value)))

        name = str(self.current().value).lower()
        name_pos = self.current().pos
        name_len = len(str(self.current().value))

        # Check for alias
        if name in self.aliases:
            self.consume()
            alias_query = self.aliases[name]
            # Parse the alias query and return its operators
            try:
                alias_parser = QueryParser(alias_query, self.aliases)
                alias_result = alias_parser.parse()
                return ('alias', name, alias_result)
            except:
                pass

        # Check for aggregate operators with function call syntax: p50(field), pct90(field)
        pct_match = re.match(r'^(?:p|pct|percentile)(\d+)$', name, re.I)
        if pct_match:
            pct = int(pct_match.group(1))
            self.consume()
            self.consume('LPAREN')
            field = self.parse_field_name()
            self.consume('RPAREN')
            alias = None
            if self.match('KEYWORD', 'as') or (self.match('IDENT') and self.current().value.lower() == 'as'):
                self.consume()
                alias = self.parse_field_name()
            by_fields = self.parse_by_clause()
            return ('percentile', pct, field, alias, by_fields)

        # Parse specific operators
        if name == 'json':
            self.consume()
            from_field = None
            if self.match('KEYWORD', 'from') or (self.match('IDENT') and self.current().value.lower() == 'from'):
                self.consume()
                from_field = self.parse_field_name()
            return ('json', from_field)

        if name == 'logfmt':
            self.consume()
            from_field = None
            if self.match('KEYWORD', 'from') or (self.match('IDENT') and self.current().value.lower() == 'from'):
                self.consume()
                from_field = self.parse_field_name()
            return ('logfmt', from_field)

        if name == 'split':
            self.consume()
            input_field = None
            separator = ','
            output_field = None

            # Check for (field) syntax
            if self.match('LPAREN'):
                self.consume('LPAREN')
                input_field = self.parse_field_name()
                self.consume('RPAREN')
                output_field = input_field  # default same as input

            # Check for 'on separator'
            if self.match('KEYWORD', 'on') or (self.match('IDENT') and self.current().value.lower() == 'on'):
                self.consume()
                tok = self.current()
                if tok.type == 'STRING':
                    separator = self.consume('STRING').value
                elif tok.type == 'IDENT':
                    separator = self.consume('IDENT').value
                else:
                    raise ParseError("unrecognized option, only the 'on' and 'as' options are available",
                                   self.text, tok.pos, len(str(tok.value)))
            elif not self.match('KEYWORD', 'as') and not self.match('IDENT', 'as') and \
                 not self.match('PIPE') and not self.match('EOF'):
                # Unknown option
                tok = self.current()
                # Collect tokens until pipe or eof for the error span
                start = tok.pos
                end = tok.pos
                while not self.match('PIPE') and not self.match('EOF'):
                    end = self.current().pos + len(str(self.current().value))
                    self.consume()
                raise ParseError("unrecognized option, only the 'on' and 'as' options are available",
                               self.text, start, end - start)

            # Check for 'as field'
            if self.match('KEYWORD', 'as') or (self.match('IDENT') and self.current().value.lower() == 'as'):
                self.consume()
                output_field = self.parse_field_name()

            if output_field is None:
                output_field = '_split'

            return ('split', input_field, separator, output_field)

        if name == 'parse':
            self.consume()
            # Parse pattern (quoted or unquoted)
            if self.match('STRING'):
                pattern = self.consume('STRING').value
            else:
                # Collect until 'as' or pipe or eof
                parts = []
                while not self.match('PIPE') and not self.match('EOF'):
                    tok = self.current()
                    if tok.type in ('KEYWORD', 'IDENT') and tok.value.lower() == 'as':
                        break
                    if tok.type == 'STAR':
                        parts.append('*')
                    else:
                        parts.append(str(tok.value))
                    self.consume()
                pattern = ''.join(parts)

            # Optional 'from field'
            from_field = None
            if self.match('KEYWORD', 'from') or (self.match('IDENT') and self.current().value.lower() == 'from'):
                self.consume()
                from_field = self.parse_field_name()

            # Parse 'as field1, field2, ...'
            fields = []
            if self.match('KEYWORD', 'as') or (self.match('IDENT') and self.current().value.lower() == 'as'):
                self.consume()
                fields.append(self.parse_field_name())
                while self.match('COMMA'):
                    self.consume('COMMA')
                    fields.append(self.parse_field_name())

            return ('parse', pattern, from_field, fields)

        if name == 'fields':
            self.consume()
            # Mode: only, except, +, -, drop, keep
            mode = 'only'  # default
            tok = self.current()
            if self.match('KEYWORD', 'only') or (self.match('IDENT') and self.current().value.lower() == 'only'):
                self.consume()
                mode = 'only'
            elif self.match('KEYWORD', 'except') or (self.match('IDENT') and self.current().value.lower() == 'except'):
                self.consume()
                mode = 'except'
            elif self.match('PLUS'):
                self.consume('PLUS')
                mode = 'only'
            elif self.match('MINUS'):
                self.consume('MINUS')
                mode = 'except'
            elif self.match('IDENT') and self.current().value.lower() == 'drop':
                self.consume()
                mode = 'except'
            elif self.match('IDENT') and self.current().value.lower() == 'keep':
                self.consume()
                mode = 'only'

            fields = [self.parse_field_name()]
            while self.match('COMMA'):
                self.consume('COMMA')
                fields.append(self.parse_field_name())
            return ('fields', mode, fields)

        if name == 'limit':
            self.consume()
            count = self.consume('NUMBER').value
            return ('limit', int(count))

        if name == 'where':
            self.consume()
            condition = self.parse_condition()
            return ('where', condition)

        if name == 'count':
            self.consume()
            # count [distinct] [field] [by ...]
            # count by ...
            count_field = None
            if not self.match('KEYWORD', 'by') and not self.match('PIPE') and not self.match('EOF'):
                if not (self.match('IDENT') and self.current().value.lower() in ('by', 'as')):
                    count_field = self.parse_field_name()

            alias = None
            if self.match('KEYWORD', 'as') or (self.match('IDENT') and self.current().value.lower() == 'as'):
                self.consume()
                alias = self.parse_field_name()

            by_fields = self.parse_by_clause()
            return ('count', count_field, alias, by_fields)

        if name == 'sum':
            self.consume()
            # sum(field) [as alias] [by ...]
            self.consume('LPAREN')
            field = self.parse_field_name()
            self.consume('RPAREN')
            alias = None
            if self.match('KEYWORD', 'as') or (self.match('IDENT') and self.current().value.lower() == 'as'):
                self.consume()
                alias = self.parse_field_name()
            by_fields = self.parse_by_clause()
            return ('sum', field, alias, by_fields)

        if name in ('min', 'max'):
            self.consume()
            self.consume('LPAREN')
            field = self.parse_field_name()
            self.consume('RPAREN')
            alias = None
            if self.match('KEYWORD', 'as') or (self.match('IDENT') and self.current().value.lower() == 'as'):
                self.consume()
                alias = self.parse_field_name()
            by_fields = self.parse_by_clause()
            return (name, field, alias, by_fields)

        if name in ('average', 'avg'):
            self.consume()
            self.consume('LPAREN')
            field = self.parse_field_name()
            self.consume('RPAREN')
            alias = None
            if self.match('KEYWORD', 'as') or (self.match('IDENT') and self.current().value.lower() == 'as'):
                self.consume()
                alias = self.parse_field_name()
            by_fields = self.parse_by_clause()
            return ('average', field, alias, by_fields)

        if name == 'sort':
            self.consume()
            # sort by field1 [asc|desc], field2, ...
            if self.match('KEYWORD', 'by') or (self.match('IDENT') and self.current().value.lower() == 'by'):
                self.consume()

            sort_keys = []
            expr = self.parse_sort_expr()
            direction = 'asc'
            if self.match('IDENT') and self.current().value.lower() in ('asc', 'desc'):
                direction = self.consume().value.lower()
            elif self.match('KEYWORD') and self.current().value in ('asc', 'desc'):
                direction = self.consume().value
            sort_keys.append((expr, direction))

            while self.match('COMMA'):
                self.consume('COMMA')
                expr = self.parse_sort_expr()
                direction = 'asc'
                if self.match('IDENT') and self.current().value.lower() in ('asc', 'desc'):
                    direction = self.consume().value.lower()
                elif self.match('KEYWORD') and self.current().value in ('asc', 'desc'):
                    direction = self.consume().value
                sort_keys.append((expr, direction))

            return ('sort', sort_keys)

        if name == 'total':
            self.consume()
            self.consume('LPAREN')
            field = self.parse_field_name()
            self.consume('RPAREN')
            alias = None
            if self.match('KEYWORD', 'as') or (self.match('IDENT') and self.current().value.lower() == 'as'):
                self.consume()
                alias = self.parse_field_name()
            return ('total', field, alias)

        if name == 'count_distinct':
            self.consume()
            self.consume('LPAREN')
            field = self.parse_field_name()
            self.consume('RPAREN')
            alias = None
            if self.match('KEYWORD', 'as') or (self.match('IDENT') and self.current().value.lower() == 'as'):
                self.consume()
                alias = self.parse_field_name()
            by_fields = self.parse_by_clause()
            return ('count_distinct', field, alias, by_fields)

        if name == 'timeslice':
            self.consume()
            self.consume('LPAREN')
            time_expr = self.parse_time_expr()
            self.consume('RPAREN')
            # duration
            duration = self.parse_duration()
            alias = '_timeslice'
            if self.match('KEYWORD', 'as') or (self.match('IDENT') and self.current().value.lower() == 'as'):
                self.consume()
                alias = self.parse_field_name()
            return ('timeslice', time_expr, duration, alias)

        # Check for multiple aggregators separated by commas on same line
        # e.g., sum(v), count by g
        # This is handled by parse_aggregators

        # Unknown operator
        # Collect the extent of the token
        self.consume()
        raise ParseError(f"Expected an operator\n  = help: {name} is not a valid operator",
                        self.text, name_pos, name_len)

    def parse_multiple_aggregators(self):
        """Parse multiple aggregators: sum(v), count by g"""
        pass

    def parse_field_name(self) -> str:
        """Parse a field name, possibly dotted or with array access"""
        tok = self.current()

        if tok.type == 'FIELD':
            # ["field name"] syntax
            self.consume('FIELD')
            return tok.value

        parts = []
        if tok.type in ('IDENT', 'KEYWORD', 'NUMBER'):
            parts.append(str(self.consume().value))
        elif tok.type == 'STRING':
            return self.consume('STRING').value
        else:
            raise ParseError(f"Expected field name, got {tok.type!r} ({tok.value!r})", 
                           self.text, tok.pos, len(str(tok.value)))

        # Dotted access and array indices
        while True:
            if self.match('DOT'):
                self.consume('DOT')
                tok = self.current()
                if tok.type in ('IDENT', 'KEYWORD', 'NUMBER'):
                    parts.append('.' + str(self.consume().value))
                else:
                    break
            elif self.match('BRACKETIDX'):
                tok = self.consume('BRACKETIDX')
                parts.append(f'[{tok.value}]')
            else:
                break

        return ''.join(parts)

    def parse_by_clause(self) -> List[str]:
        """Parse optional 'by field1, field2' clause"""
        if self.match('KEYWORD', 'by') or (self.match('IDENT') and self.current().value.lower() == 'by'):
            self.consume()
            fields = [self.parse_field_name()]
            while self.match('COMMA'):
                self.consume('COMMA')
                fields.append(self.parse_field_name())
            return fields
        return []

    def parse_condition(self):
        """Parse a where condition: field op value"""
        left = self.parse_expr()
        if self.match('OP'):
            op = self.consume('OP').value
            right = self.parse_expr()
            return ('binop', op, left, right)
        return ('truthy', left)

    def parse_expr(self):
        """Parse an expression"""
        return self.parse_additive()

    def parse_additive(self):
        left = self.parse_multiplicative()
        while self.match('PLUS') or self.match('MINUS'):
            op = self.consume().value
            right = self.parse_multiplicative()
            left = ('arith', op, left, right)
        return left

    def parse_multiplicative(self):
        left = self.parse_primary_expr()
        while self.match('DIV') or self.match('MOD'):
            op = self.consume().value
            right = self.parse_primary_expr()
            left = ('arith', op, left, right)
        return left

    def parse_primary_expr(self):
        tok = self.current()

        if tok.type == 'NUMBER':
            self.consume()
            return ('literal', tok.value)

        if tok.type == 'STRING':
            self.consume()
            return ('literal', tok.value)

        if tok.type == 'MINUS':
            self.consume()
            expr = self.parse_primary_expr()
            return ('neg', expr)

        # Function call: length(field)
        if tok.type == 'IDENT' and self.peek().type == 'LPAREN':
            fname = self.consume('IDENT').value.lower()
            self.consume('LPAREN')
            args = []
            if not self.match('RPAREN'):
                args.append(self.parse_field_name())
                while self.match('COMMA'):
                    self.consume('COMMA')
                    args.append(self.parse_field_name())
            self.consume('RPAREN')
            return ('func', fname, args)

        # Field name
        fname = self.parse_field_name()
        return ('field', fname)

    def parse_sort_expr(self):
        """Parse a sort expression"""
        return self.parse_additive()

    def parse_time_expr(self):
        """Parse time expression like parseDate(field)"""
        tok = self.current()
        if tok.type == 'IDENT' and tok.value.lower() == 'parsedate':
            self.consume()
            self.consume('LPAREN')
            field = self.parse_field_name()
            self.consume('RPAREN')
            return ('parseDate', field)
        return self.parse_primary_expr()

    def parse_duration(self):
        """Parse a duration like 5m, 1h, 30s"""
        tok = self.current()
        if tok.type == 'NUMBER':
            num = self.consume('NUMBER').value
            # Unit should follow immediately as IDENT
            if self.match('IDENT'):
                unit = self.consume('IDENT').value
                return (num, unit)
            return (num, 's')
        raise ParseError("Expected duration", self.text, tok.pos)


