#!/usr/bin/env python3
"""angle-grinder (agrind) - slice and dice log files"""
import sys, os, re, json, math, argparse
from datetime import datetime, timezone, timedelta
from collections import defaultdict, OrderedDict
from typing import Optional, List, Dict, Any, Tuple

def format_value(val):
    if val is None: return "None"
    if isinstance(val, bool): return "true" if val else "false"
    if isinstance(val, int): return str(val)
    if isinstance(val, float):
        if not math.isnan(val) and not math.isinf(val) and val == math.floor(val) and abs(val) < 1e15:
            return str(int(val))
        return f"{val:.2f}"
    if isinstance(val, list):
        return "[" + ", ".join(format_value(v) for v in val) + "]"
    if isinstance(val, dict):
        items = ", ".join(f"{k}:{format_value(v)}" for k,v in sorted(val.items()))
        return "{" + items + "}"
    return str(val)

def to_num(val):
    if isinstance(val, bool): return None
    if isinstance(val, (int, float)): return float(val)
    if isinstance(val, str):
        try: return float(val)
        except: return None
    return None

def get_field(row, field):
    if field in row: return row[field]
    parts = split_path(field)
    if len(parts) <= 1: return None
    val = row.get(parts[0])
    for p in parts[1:]:
        if val is None: return None
        if isinstance(p, int):
            if isinstance(val, list):
                try: val = val[p]
                except IndexError: return None
            else: return None
        else:
            if isinstance(val, dict): val = val.get(p)
            else: return None
    return val

def split_path(field):
    parts = []
    cur = ''
    i = 0
    while i < len(field):
        if field[i] == '.':
            if cur: parts.append(cur)
            cur = ''; i += 1
        elif field[i] == '[':
            if cur: parts.append(cur)
            cur = ''
            j = i+1
            while j < len(field) and field[j] != ']': j += 1
            try: parts.append(int(field[i+1:j]))
            except: parts.append(field[i+1:j])
            i = j+1
        else:
            cur += field[i]; i += 1
    if cur: parts.append(cur)
    return parts

def parse_json_obj(s):
    try:
        val = json.loads(s)
        if isinstance(val, dict): return val
        return None
    except: return None

def parse_logfmt_str(s):
    result = {}
    i = 0
    while i < len(s):
        while i < len(s) and s[i] == ' ': i += 1
        if i >= len(s): break
        key_start = i
        while i < len(s) and s[i] not in ('=', ' '): i += 1
        key = s[key_start:i]
        if not key: i += 1; continue
        if i >= len(s) or s[i] != '=':
            result[key] = ''
            continue
        i += 1
        if i < len(s) and s[i] == '"':
            i += 1
            val_parts = []
            while i < len(s) and s[i] != '"':
                if s[i] == '\\' and i+1 < len(s): val_parts.append(s[i+1]); i += 2
                else: val_parts.append(s[i]); i += 1
            result[key] = ''.join(val_parts)
            if i < len(s): i += 1
        else:
            val_start = i
            while i < len(s) and s[i] != ' ': i += 1
            result[key] = s[val_start:i]
    return result

def glob_match(pattern, text, case_sensitive=True):
    if not case_sensitive:
        pattern = pattern.lower()
        text = text.lower()
    parts = pattern.split('*')
    if len(parts) == 1: return pattern in text
    regex = '.*?'.join(re.escape(p) for p in parts)
    return bool(re.search(regex, text, re.DOTALL))

def apply_filter(line, filt):
    if filt is None: return True
    k = filt[0]
    if k == 'star': return True
    if k == 'exact': return filt[1] in line
    if k == 'glob': return glob_match(filt[1], line, False)
    if k == 'and': return apply_filter(line, filt[1]) and apply_filter(line, filt[2])
    if k == 'or': return apply_filter(line, filt[1]) or apply_filter(line, filt[2])
    if k == 'not': return not apply_filter(line, filt[1])
    return True

# ===================== PARSER =====================

class ParseError(Exception):
    def __init__(self, msg, query='', pos=0, length=1):
        self.msg = msg; self.query = query; self.pos = pos; self.length = length
        super().__init__(msg)
    def format(self):
        lines = [f"error: {self.msg}", "  |", f"1 | {self.query}",
                 f"  | {' '*self.pos}{'^'*max(1,self.length)}", "  |"]
        return "\n".join(lines)

class Tok:
    __slots__ = ['t','v','p']
    def __init__(self,t,v,p): self.t=t; self.v=v; self.p=p
    def __repr__(self): return f"Tok({self.t},{self.v!r})"

def tokenize(text):
    toks = []
    i = 0
    while i < len(text):
        c = text[i]
        if c.isspace(): i += 1; continue
        if c == '|': toks.append(Tok('PIPE','|',i)); i += 1; continue
        if c == ',': toks.append(Tok('COMMA',',',i)); i += 1; continue
        if c == '(': toks.append(Tok('LP','(',i)); i += 1; continue
        if c == ')': toks.append(Tok('RP',')',i)); i += 1; continue
        if c == '+': toks.append(Tok('PLUS','+',i)); i += 1; continue
        if c == '/': toks.append(Tok('DIV','/',i)); i += 1; continue
        if c == '%': toks.append(Tok('MOD','%',i)); i += 1; continue
        if c == '.': toks.append(Tok('DOT','.',i)); i += 1; continue
        if c == '-':
            toks.append(Tok('MINUS','-',i)); i += 1; continue
        if c == '*':
            toks.append(Tok('STAR','*',i)); i += 1; continue
        if text[i:i+2] in ('==','!=','>=','<='):
            toks.append(Tok('OP',text[i:i+2],i)); i += 2; continue
        if c in '<>':
            toks.append(Tok('OP',c,i)); i += 1; continue
        if c == '[':
            if i+1 < len(text) and text[i+1] == '"':
                end = text.find('"]', i+2)
                if end >= 0:
                    toks.append(Tok('QFIELD',text[i+2:end],i)); i = end+2; continue
            j = i+1
            neg = j < len(text) and text[j] == '-'
            if neg: j += 1
            while j < len(text) and text[j].isdigit(): j += 1
            if j < len(text) and text[j] == ']' and j > i+1+(1 if neg else 0):
                toks.append(Tok('BIDX',text[i+1:j],i)); i = j+1; continue
            toks.append(Tok('LBRK','[',i)); i += 1; continue
        if c == ']': toks.append(Tok('RBRK',']',i)); i += 1; continue
        if c == '"':
            j = i+1; s = []
            while j < len(text) and text[j] != '"':
                if text[j] == '\\' and j+1 < len(text): s.append(text[j+1]); j += 2
                else: s.append(text[j]); j += 1
            toks.append(Tok('STR',''.join(s),i)); i = j+1; continue
        if c.isdigit():
            j = i
            while j < len(text) and (text[j].isdigit() or text[j] == '.'): j += 1
            ns = text[i:j]
            try:
                n = float(ns) if '.' in ns else int(ns)
                toks.append(Tok('NUM',n,i))
            except:
                toks.append(Tok('IDENT',ns,i))
            i = j; continue
        if c.isalpha() or c == '_':
            j = i
            while j < len(text) and (text[j].isalnum() or text[j] == '_'): j += 1
            toks.append(Tok('IDENT',text[i:j],i)); i = j; continue
        i += 1
    toks.append(Tok('EOF','',len(text)))
    return toks

KW = {'and','or','not','by','as','from','on','asc','desc','only','except',
      'drop','keep','json','logfmt','split','parse','fields','limit','where',
      'timeslice','total','count','sum','min','max','average','sort','avg',
      'count_distinct','parsedate'}

class Parser:
    def __init__(self, text, aliases=None):
        self.text = text
        self.aliases = aliases or {}
        self.toks = tokenize(text)
        self.p = 0

    def cur(self): return self.toks[self.p]
    def peek(self, n=1):
        i = self.p+n
        return self.toks[i] if i < len(self.toks) else self.toks[-1]

    def eat(self, t=None, v=None):
        tok = self.toks[self.p]
        if t and tok.t != t:
            raise ParseError(f"Expected {t} got {tok.t!r}", self.text, tok.p, len(str(tok.v)) or 1)
        if v is not None and tok.v != v:
            raise ParseError(f"Expected {v!r} got {tok.v!r}", self.text, tok.p, len(str(tok.v)) or 1)
        self.p += 1
        return tok

    def is_(self, t=None, v=None):
        tok = self.cur()
        if t and tok.t != t: return False
        if v is not None:
            if isinstance(v, (list,tuple)): return str(tok.v).lower() in v
            return str(tok.v).lower() == str(v).lower()
        return True

    def is_kw(self, *words):
        tok = self.cur()
        return tok.t == 'IDENT' and tok.v.lower() in words

    def parse(self):
        filt = self.parse_filter()
        ops = []
        while self.is_('PIPE'):
            self.eat('PIPE')
            op = self.parse_op()
            if op is not None:
                if isinstance(op, list): ops.extend(op)
                else: ops.append(op)
        if not self.is_('EOF'):
            tok = self.cur()
            raise ParseError(f"Unexpected: {tok.v!r}", self.text, tok.p, len(str(tok.v)) or 1)
        return filt, ops

    def parse_filter(self):
        return self.parse_or()

    def parse_or(self):
        l = self.parse_and()
        while self.is_kw('or'):
            self.eat()
            r = self.parse_and()
            l = ('or', l, r)
        return l

    def parse_and(self):
        l = self.parse_not()
        while self.is_kw('and'):
            self.eat()
            r = self.parse_not()
            l = ('and', l, r)
        return l

    def parse_not(self):
        if self.is_kw('not'):
            self.eat()
            return ('not', self.parse_prim_filter())
        return self.parse_prim_filter()

    def parse_prim_filter(self):
        tok = self.cur()
        if tok.t == 'LP':
            self.eat('LP')
            f = self.parse_filter()
            self.eat('RP')
            return f
        if tok.t == 'STAR':
            self.eat('STAR')
            return ('star',)
        if tok.t == 'STR':
            self.eat('STR')
            return ('exact', tok.v)
        # unquoted glob
        if tok.t in ('IDENT','NUM'):
            parts = []
            start = tok.p
            end = tok.p
            while True:
                tok2 = self.cur()
                if tok2.t in ('PIPE','EOF','RP'): break
                if tok2.t == 'IDENT' and tok2.v.lower() in ('and','or','not'): break
                if tok2.t == 'STAR': parts.append('*')
                elif tok2.t in ('IDENT','NUM','STR'): parts.append(str(tok2.v))
                else: break
                end = tok2.p + len(str(tok2.v))
                self.eat()
            if parts:
                return ('glob', ''.join(parts))
        raise ParseError("Expected filter", self.text, tok.p, len(str(tok.v)) or 1)

    def parse_field(self):
        tok = self.cur()
        if tok.t == 'QFIELD':
            self.eat('QFIELD')
            return tok.v
        if tok.t == 'STR':
            self.eat('STR')
            return tok.v
        if tok.t not in ('IDENT','NUM'):
            raise ParseError(f"Expected field name", self.text, tok.p, len(str(tok.v)) or 1)
        parts = [str(self.eat().v)]
        while True:
            if self.is_('DOT'):
                self.eat('DOT')
                if self.cur().t in ('IDENT','NUM'):
                    parts.append('.' + str(self.eat().v))
                else: break
            elif self.is_('BIDX'):
                t = self.eat('BIDX')
                parts.append(f'[{t.v}]')
            else: break
        return ''.join(parts)

    def parse_by(self):
        if self.is_kw('by'):
            self.eat()
            fields = [self.parse_field()]
            while self.is_('COMMA'):
                self.eat('COMMA')
                fields.append(self.parse_field())
            return fields
        return []

    def parse_as(self):
        if self.is_kw('as'):
            self.eat()
            return self.parse_field()
        return None

    def parse_op(self):
        tok = self.cur()
        if tok.t not in ('IDENT','NUM','QFIELD'):
            raise ParseError("Expected an operator", self.text, tok.p, len(str(tok.v)) or 1)
        name = str(tok.v).lower()
        name_pos = tok.p
        name_len = len(str(tok.v))

        # percentile shorthand
        m = re.match(r'^(?:p|pct|percentile)(\d+)$', name, re.I)
        if m:
            pct = int(m.group(1))
            self.eat()
            return self.parse_agg_list(('percentile', pct, None, None, None))

        # check aliases
        if name in self.aliases:
            self.eat()
            aq = self.aliases[name]
            try:
                ap = Parser(aq, self.aliases)
                _, aops = ap.parse()
                return aops
            except:
                return []

        if name == 'json':
            self.eat()
            from_f = None
            if self.is_kw('from'): self.eat(); from_f = self.parse_field()
            return ('json', from_f)

        if name == 'logfmt':
            self.eat()
            from_f = None
            if self.is_kw('from'): self.eat(); from_f = self.parse_field()
            return ('logfmt', from_f)

        if name == 'split':
            self.eat()
            in_f = None; sep = ','; out_f = None
            if self.is_('LP'):
                self.eat('LP'); in_f = self.parse_field(); self.eat('RP')
                out_f = in_f
            if self.is_kw('on'):
                self.eat()
                if self.cur().t in ('STR','IDENT','NUM'):
                    sep = str(self.eat().v)
                else:
                    t = self.cur(); start = t.p
                    while not self.is_('PIPE') and not self.is_('EOF'): self.eat()
                    raise ParseError("unrecognized option, only the 'on' and 'as' options are available",
                                     self.text, start, self.cur().p - start)
            elif not self.is_kw('as') and not self.is_('PIPE') and not self.is_('EOF'):
                t = self.cur(); start = t.p; end = t.p
                while not self.is_('PIPE') and not self.is_('EOF'):
                    end = self.cur().p + len(str(self.cur().v)); self.eat()
                raise ParseError("unrecognized option, only the 'on' and 'as' options are available",
                                 self.text, start, max(1, end - start))
            if self.is_kw('as'): self.eat(); out_f = self.parse_field()
            if out_f is None: out_f = '_split'
            return ('split', in_f, sep, out_f)

        if name == 'parse':
            self.eat()
            if self.cur().t == 'STR':
                pattern = self.eat('STR').v
            else:
                parts = []
                while not self.is_('PIPE') and not self.is_('EOF'):
                    t = self.cur()
                    if t.t == 'IDENT' and t.v.lower() in ('as','from'): break
                    if t.t == 'STAR': parts.append('*')
                    else: parts.append(str(t.v))
                    self.eat()
                pattern = ''.join(parts)
            from_f = None
            if self.is_kw('from'): self.eat(); from_f = self.parse_field()
            fields = []
            if self.is_kw('as'):
                self.eat()
                fields.append(self.parse_field())
                while self.is_('COMMA'): self.eat(); fields.append(self.parse_field())
            return ('parse', pattern, from_f, fields)

        if name == 'fields':
            self.eat()
            mode = 'only'
            if self.is_kw('only'): self.eat(); mode = 'only'
            elif self.is_kw('except'): self.eat(); mode = 'except'
            elif self.is_kw('drop'): self.eat(); mode = 'except'
            elif self.is_kw('keep'): self.eat(); mode = 'only'
            elif self.is_('PLUS'): self.eat(); mode = 'only'
            elif self.is_('MINUS'): self.eat(); mode = 'except'
            fs = [self.parse_field()]
            while self.is_('COMMA'): self.eat(); fs.append(self.parse_field())
            return ('fields', mode, fs)

        if name == 'limit':
            self.eat()
            n = self.eat('NUM').v
            return ('limit', int(n))

        if name == 'where':
            self.eat()
            cond = self.parse_cond()
            return ('where', cond)

        if name == 'total':
            self.eat()
            self.eat('LP'); f = self.parse_field(); self.eat('RP')
            alias = self.parse_as()
            return ('total', f, alias)

        if name == 'timeslice':
            self.eat()
            self.eat('LP'); te = self.parse_time_expr(); self.eat('RP')
            dur = self.parse_duration()
            alias = '_timeslice'
            if self.is_kw('as'): self.eat(); alias = self.parse_field()
            return ('timeslice', te, dur, alias)

        # aggregators (possibly comma-separated)
        if name in ('count','sum','min','max','average','avg','count_distinct'):
            first = self.parse_single_agg()
            return self.parse_agg_list(first)

        # Unknown
        self.eat()
        raise ParseError(f"Expected an operator\n  = help: {name} is not a valid operator",
                         self.text, name_pos, name_len)

    def parse_single_agg(self):
        tok = self.cur()
        name = str(tok.v).lower()
        name_pos = tok.p; name_len = len(str(tok.v))

        m = re.match(r'^(?:p|pct|percentile)(\d+)$', name, re.I)
        if m:
            pct = int(m.group(1)); self.eat()
            self.eat('LP'); f = self.parse_field(); self.eat('RP')
            alias = self.parse_as()
            return ('percentile', pct, f, alias, None)

        if name == 'count':
            self.eat()
            f = None
            if not self.is_kw('by') and not self.is_kw('as') and \
               not self.is_('PIPE') and not self.is_('EOF') and not self.is_('COMMA'):
                # peek - if next is not pipe/comma/eof/by, it might be a field
                if self.cur().t in ('IDENT','QFIELD','NUM') and \
                   not (self.cur().t == 'IDENT' and self.cur().v.lower() in ('by','as')):
                    f = self.parse_field()
            alias = self.parse_as()
            return ('count', f, alias, None)

        if name in ('sum','min','max','average','avg','count_distinct'):
            self.eat()
            self.eat('LP'); f = self.parse_field(); self.eat('RP')
            alias = self.parse_as()
            op = 'average' if name == 'avg' else name
            return (op, f, alias, None)

        raise ParseError(f"Expected aggregator", self.text, name_pos, name_len)

    def parse_agg_list(self, first):
        aggs = [first]
        while self.is_('COMMA'):
            self.eat('COMMA')
            aggs.append(self.parse_single_agg())
        by = self.parse_by()
        # Attach by to all aggs
        result = []
        for a in aggs:
            lst = list(a); lst[-1] = by; result.append(tuple(lst))
        if len(result) == 1: return result[0]
        return ('multi_agg', result)

    def parse_cond(self):
        l = self.parse_arith()
        if self.is_('OP'):
            op = self.eat('OP').v
            r = self.parse_arith()
            return ('cmp', op, l, r)
        return ('truthy', l)

    def parse_arith(self):
        l = self.parse_mul()
        while self.is_('PLUS') or self.is_('MINUS'):
            op = self.eat().v
            r = self.parse_mul()
            l = ('arith', op, l, r)
        return l

    def parse_mul(self):
        l = self.parse_unary()
        while self.is_('DIV') or self.is_('MOD') or self.is_('STAR'):
            op = self.eat().v
            r = self.parse_unary()
            l = ('arith', op, l, r)
        return l

    def parse_unary(self):
        if self.is_('MINUS'):
            self.eat(); e = self.parse_primary_expr()
            return ('neg', e)
        return self.parse_primary_expr()

    def parse_primary_expr(self):
        tok = self.cur()
        if tok.t == 'NUM': self.eat(); return ('lit', tok.v)
        if tok.t == 'STR': self.eat(); return ('lit', tok.v)
        if tok.t == 'LP':
            self.eat('LP'); e = self.parse_arith(); self.eat('RP'); return e
        # function call
        if tok.t == 'IDENT' and self.peek().t == 'LP':
            fname = self.eat('IDENT').v.lower()
            self.eat('LP')
            args = []
            if not self.is_('RP'):
                args.append(self.parse_field())
                while self.is_('COMMA'): self.eat(); args.append(self.parse_field())
            self.eat('RP')
            return ('func', fname, args)
        f = self.parse_field()
        return ('field', f)

    def parse_time_expr(self):
        if self.cur().t == 'IDENT' and self.cur().v.lower() == 'parsedate':
            self.eat()
            self.eat('LP'); f = self.parse_field(); self.eat('RP')
            return ('parseDate', f)
        return self.parse_arith()

    def parse_duration(self):
        tok = self.cur()
        if tok.t == 'NUM':
            n = self.eat('NUM').v
            if self.cur().t == 'IDENT':
                unit = self.eat('IDENT').v
                return (float(n), unit)
            return (float(n), 's')
        raise ParseError("Expected duration", self.text, tok.p)


# ===================== EVALUATORS =====================

def eval_expr(expr, row):
    if expr is None: return None
    k = expr[0]
    if k == 'lit': return expr[1]
    if k == 'field': return get_field(row, expr[1])
    if k == 'neg':
        v = eval_expr(expr[1], row)
        n = to_num(v)
        return -n if n is not None else None
    if k == 'arith':
        _, op, le, re_ = expr
        lv = to_num(eval_expr(le, row)); rv = to_num(eval_expr(re_, row))
        if lv is None or rv is None: return None
        if op == '+': return lv + rv
        if op == '-': return lv - rv
        if op == '/': return lv / rv if rv != 0 else None
        if op == '*': return lv * rv
        if op == '%': return lv % rv if rv != 0 else None
    if k == 'func':
        fname = expr[1]; args = expr[2]
        if fname == 'length':
            v = get_field(row, args[0]) if args else None
            return len(str(v)) if v is not None else 0
    return None

def eval_cond(cond, row):
    if cond is None: return True
    k = cond[0]
    if k == 'truthy':
        v = eval_expr(cond[1], row)
        return bool(v)
    if k == 'cmp':
        _, op, le, re_ = cond
        lv = eval_expr(le, row); rv = eval_expr(re_, row)
        ln = to_num(lv); rn = to_num(rv)
        if op == '==':
            if ln is not None and rn is not None: return ln == rn
            return str(lv) == str(rv)
        if op == '!=':
            if ln is not None and rn is not None: return ln != rn
            return str(lv) != str(rv)
        if ln is not None and rn is not None:
            if op == '>': return ln > rn
            if op == '<': return ln < rn
            if op == '>=': return ln >= rn
            if op == '<=': return ln <= rn
        return False
    return True

def eval_sort_key(expr, row):
    if expr[0] == 'field':
        v = get_field(row, expr[1])
        n = to_num(v)
        return (0, n) if n is not None else (1, str(v) if v is not None else '')
    v = eval_expr(expr, row)
    n = to_num(v)
    return (0, n) if n is not None else (1, str(v) if v is not None else '')


# ===================== AGGREGATE STATE =====================

class AggState:
    def __init__(self, ops, by_fields):
        self.ops = ops  # list of (op_type, field, alias)
        self.by_fields = by_fields
        self.groups = OrderedDict()  # key -> {agg_name: state}

    def get_key(self, row):
        return tuple(str(get_field(row, f)) for f in self.by_fields)

    def get_group_vals(self, row):
        return {f: get_field(row, f) for f in self.by_fields}

    def init_group(self, key, row):
        state = {'_group_vals': self.get_group_vals(row)}
        for op in self.ops:
            ot = op[0]
            if ot in ('count','sum','min','max','average','count_distinct'):
                aname = op[2] or f'_{ot}'
                if ot == 'count': state[aname] = 0
                elif ot == 'sum': state[aname] = 0.0
                elif ot == 'min': state[aname] = None
                elif ot == 'max': state[aname] = None
                elif ot == 'average': state[aname] = [0.0, 0]  # sum, count
                elif ot == 'count_distinct': state[aname] = set()
            elif ot == 'percentile':
                pct, f, alias, _ = op[1], op[2], op[3], op[4]
                aname = alias or f'p{pct}'
                state[aname] = []
        self.groups[key] = state

    def process(self, row):
        key = self.get_key(row)
        if key not in self.groups:
            self.init_group(key, row)
        state = self.groups[key]
        for op in self.ops:
            ot = op[0]
            if ot == 'count':
                f = op[1]; aname = op[2] or '_count'
                if f is None or get_field(row, f) is not None:
                    state[aname] += 1
            elif ot == 'sum':
                f = op[1]; aname = op[2] or '_sum'
                v = to_num(get_field(row, f))
                if v is not None: state[aname] += v
            elif ot == 'min':
                f = op[1]; aname = op[2] or '_min'
                v = to_num(get_field(row, f))
                if v is not None:
                    if state[aname] is None or v < state[aname]: state[aname] = v
            elif ot == 'max':
                f = op[1]; aname = op[2] or '_max'
                v = to_num(get_field(row, f))
                if v is not None:
                    if state[aname] is None or v > state[aname]: state[aname] = v
            elif ot == 'average':
                f = op[1]; aname = op[2] or '_average'
                v = to_num(get_field(row, f))
                if v is not None: state[aname][0] += v; state[aname][1] += 1
            elif ot == 'count_distinct':
                f = op[1]; aname = op[2] or '_countDistinct'
                v = get_field(row, f)
                if v is not None: state[aname].add(str(v))
            elif ot == 'percentile':
                pct, f, alias, _ = op[1], op[2], op[3], op[4]
                aname = alias or f'p{pct}'
                v = to_num(get_field(row, f))
                if v is not None: state[aname].append(v)

    def finalize(self):
        rows = []
        for key, state in self.groups.items():
            row = dict(state['_group_vals'])
            for op in self.ops:
                ot = op[0]
                if ot == 'count':
                    aname = op[2] or '_count'
                    row[aname] = state[aname]
                elif ot == 'sum':
                    aname = op[2] or '_sum'
                    v = state[aname]
                    row[aname] = int(v) if v == int(v) else v
                elif ot in ('min','max'):
                    aname = op[2] or f'_{ot}'
                    v = state[aname]
                    if v is not None: row[aname] = int(v) if v == int(v) else v
                    else: row[aname] = None
                elif ot == 'average':
                    aname = op[2] or '_average'
                    s, c = state[aname]
                    if c > 0:
                        v = s / c
                        row[aname] = int(v) if v == int(v) else v
                    else: row[aname] = None
                elif ot == 'count_distinct':
                    aname = op[2] or '_countDistinct'
                    row[aname] = len(state[aname])
                elif ot == 'percentile':
                    pct, f, alias, _ = op[1], op[2], op[3], op[4]
                    aname = alias or f'p{pct}'
                    vals = sorted(state[aname])
                    if vals:
                        idx = max(0, math.ceil(pct / 100.0 * len(vals)) - 1)
                        v = vals[idx]
                        row[aname] = int(v) if v == int(v) else v
                    else: row[aname] = None
            rows.append(row)
        return rows


# ===================== PIPELINE =====================

def run_op(op, rows, is_tty=False):
    """Apply a single operator to rows. Returns (new_rows, is_aggregate, agg_state)"""
    ot = op[0]

    if ot == 'json':
        from_f = op[1]
        result = []
        for row in rows:
            if isinstance(row, str):
                src = row; orig = {}
            else:
                src = get_field(row, from_f) if from_f else row.get('_raw', '')
                orig = dict(row) if not from_f else dict(row)
                if from_f: src = get_field(row, from_f)
                else: src = row.get('_raw', '')
            if src is None: continue
            parsed = parse_json_obj(str(src))
            if parsed is None:
                print(f"error: Expected JSON, found {src}", file=sys.stderr)
                continue
            if from_f:
                new_row = dict(orig)
                for k,v in flatten_json(parsed).items():
                    new_row[k] = v
            else:
                new_row = flatten_json(parsed)
            result.append(new_row)
        return result, False, None

    if ot == 'logfmt':
        from_f = op[1]
        result = []
        for row in rows:
            if isinstance(row, str): src = row; orig = {}
            else:
                orig = dict(row)
                src = get_field(row, from_f) if from_f else row.get('_raw', '')
            if src is None: continue
            parsed = parse_logfmt_str(str(src))
            if from_f:
                new_row = dict(orig)
                new_row.update(parsed)
            else:
                new_row = parsed
            result.append(new_row)
        return result, False, None

    if ot == 'split':
        _, in_f, sep, out_f = op
        result = []
        for row in rows:
            if isinstance(row, str): src = row; orig = {}
            else:
                orig = dict(row)
                src = get_field(row, in_f) if in_f else row.get('_raw', '')
            if src is None: continue
            parts = str(src).split(sep)
            new_row = dict(orig)
            new_row[out_f] = parts
            result.append(new_row)
        return result, False, None

    if ot == 'parse':
        _, pattern, from_f, fields = op
        result = []
        regex = pattern_to_regex(pattern)
        for row in rows:
            if isinstance(row, str): src = row; orig = {}
            else:
                orig = dict(row)
                src = get_field(row, from_f) if from_f else row.get('_raw', '')
            if src is None: continue
            m = regex.search(str(src), re.IGNORECASE)
            if m:
                new_row = dict(orig)
                for i, f in enumerate(fields):
                    if i < len(m.groups()):
                        new_row[f] = m.group(i+1)
                result.append(new_row)
            # If no match, drop the row
        return result, False, None

    if ot == 'fields':
        _, mode, fs = op
        result = []
        for row in rows:
            if isinstance(row, str):
                result.append(row); continue
            if mode == 'only':
                new_row = {k: v for k,v in row.items() if k in fs}
            else:  # except
                new_row = {k: v for k,v in row.items() if k not in fs}
            result.append(new_row)
        return result, False, None

    if ot == 'limit':
        return rows[:op[1]], False, None

    if ot == 'where':
        _, cond = op
        result = []
        for row in rows:
            if isinstance(row, str):
                result.append(row); continue
            if eval_cond(cond, row):
                result.append(row)
        return result, False, None

    if ot == 'total':
        _, field, alias = op
        aname = alias or '_total'
        running = 0.0
        result = []
        for row in rows:
            if isinstance(row, str): result.append(row); continue
            v = to_num(get_field(row, field))
            if v is not None: running += v
            new_row = dict(row)
            new_row[aname] = int(running) if running == int(running) else running
            result.append(new_row)
        return result, False, None

    if ot == 'timeslice':
        _, te, dur, alias = op
        num, unit = dur
        unit_secs = {'ns': 1e-9, 'us': 1e-6, 'ms': 1e-3, 's': 1,
                     'm': 60, 'h': 3600, 'd': 86400, 'w': 604800}
        secs = num * unit_secs.get(unit, 1)
        result = []
        for row in rows:
            if isinstance(row, str): result.append(row); continue
            t = eval_time_expr(te, row)
            if t is not None:
                ts = t.timestamp()
                sliced = int(ts / secs) * secs
                dt = datetime.fromtimestamp(sliced, tz=timezone.utc)
                new_row = dict(row)
                new_row[alias] = dt.strftime('%Y-%m-%d %H:%M:%S UTC')
                result.append(new_row)
        return result, False, None

    if ot in ('count','sum','min','max','average','count_distinct','percentile'):
        by = op[-1] or []
        agg = AggState([op], by)
        for row in rows:
            if isinstance(row, str): continue
            agg.process(row)
        return agg.finalize(), True, agg

    if ot == 'multi_agg':
        agg_list = op[1]
        by = agg_list[0][-1] if agg_list else []
        agg = AggState(agg_list, by)
        for row in rows:
            if isinstance(row, str): continue
            agg.process(row)
        return agg.finalize(), True, agg

    if ot == 'sort':
        sort_keys = op[1]
        def sort_key(row):
            if isinstance(row, str): return (1, '')
            k = []
            for expr, direction in sort_keys:
                v = eval_sort_key(expr, row)
                if direction == 'desc':
                    # Negate for descending
                    if v[0] == 0: k.append((0, -v[1]))
                    else: k.append((2, v[1]))  # strings go last in desc
                else:
                    k.append(v)
            return k
        return sorted(rows, key=sort_key), False, None

    return rows, False, None

def pattern_to_regex(pattern):
    """Convert parse pattern with * wildcards to regex"""
    parts = pattern.split('*')
    if len(parts) == 1:
        return re.compile(re.escape(pattern), re.IGNORECASE)
    # Non-greedy for all but last
    regex_parts = []
    for i, p in enumerate(parts):
        regex_parts.append(re.escape(p))
        if i < len(parts) - 1:
            regex_parts.append('(.*?)')  # non-greedy capture
    # Last capture is greedy (no trailing literal)
    # Actually we need to handle the last * specially
    # If pattern ends with *, last capture should be greedy
    # If pattern ends with literal, last capture is non-greedy before that literal
    regex = ''.join(regex_parts)
    # The last (.*?) should actually be (.*) if it's at the end
    # Let's check: if parts[-1] == '', then pattern ends with *, last capture is greedy
    if parts[-1] == '':
        regex = regex[:-len('(.*?)')]  + '(.*)'
    return re.compile(regex, re.IGNORECASE | re.DOTALL)

def eval_time_expr(te, row):
    if te is None: return None
    if te[0] == 'parseDate':
        v = get_field(row, te[1])
        if v is None: return None
        return parse_date(str(v))
    return None

def parse_date(s):
    formats = [
        '%Y-%m-%dT%H:%M:%SZ',
        '%Y-%m-%dT%H:%M:%S.%fZ',
        '%Y-%m-%dT%H:%M:%S%z',
        '%Y-%m-%d %H:%M:%S',
        '%Y-%m-%d',
    ]
    for fmt in formats:
        try:
            dt = datetime.strptime(s, fmt)
            if dt.tzinfo is None: dt = dt.replace(tzinfo=timezone.utc)
            return dt
        except: pass
    return None

def flatten_json(obj, prefix=''):
    """Flatten JSON object, but keep nested dicts/arrays as-is for display"""
    # Don't flatten - keep as-is, access via dotted paths
    return {k: v for k, v in obj.items()}


# ===================== OUTPUT FORMATTING =====================

def format_row_legacy(row):
    """Format a row in legacy [k=v] format"""
    if isinstance(row, str): return row
    parts = []
    for k in sorted(row.keys()):
        v = format_value(row[k])
        # Use ["k"] format if key has spaces, dots, or quotes
        if ' ' in k or '"' in k:
            parts.append(f'["{k}"={v}]')
        else:
            parts.append(f'[{k}={v}]')
    return '  '.join(parts)

def format_row_json(row):
    if isinstance(row, str):
        try: return json.dumps(json.loads(row))
        except: return json.dumps({'_raw': row})
    def to_json(v):
        if isinstance(v, dict): return {k: to_json(vv) for k,vv in v.items()}
        if isinstance(v, list): return [to_json(x) for x in v]
        return v
    return json.dumps({k: to_json(v) for k,v in sorted(row.items())})

def format_row_logfmt(row):
    if isinstance(row, str): return row
    parts = []
    for k in sorted(row.keys()):
        v = format_value(row[k])
        if ' ' in v or '=' in v or '"' in v:
            v = '"' + v.replace('"', '\\"') + '"'
        parts.append(f'{k}={v}')
    return ' '.join(parts)

def format_row_fmt(row, fmt):
    if isinstance(row, str): return row
    result = fmt
    for k, v in row.items():
        result = result.replace('{' + k + '}', format_value(v))
    return result

def get_col_widths(rows, min_width=4):
    """Get column widths for aggregate table output"""
    if not rows: return {}
    all_keys = []
    seen = set()
    for row in rows:
        if isinstance(row, dict):
            for k in row.keys():
                if k not in seen: all_keys.append(k); seen.add(k)
    widths = {}
    for k in all_keys:
        w = len(str(k))
        for row in rows:
            if isinstance(row, dict):
                v = format_value(row.get(k))
                w = max(w, len(v))
        widths[k] = max(w, min_width)
    return widths, all_keys

def print_aggregate_table(rows, out=sys.stdout):
    """Print aggregate results as a formatted table"""
    if not rows:
        print("No data", file=out)
        return
    widths, keys = get_col_widths(rows)
    if not keys:
        print("No data", file=out)
        return
    # Header
    header = '  '.join(k.ljust(widths[k]) for k in keys)
    sep = '-' * (len(header) + 2)
    print(header.rstrip(), file=out)
    print(sep, file=out)
    for row in rows:
        if isinstance(row, dict):
            parts = []
            for k in keys:
                v = format_value(row.get(k))
                parts.append(v.ljust(widths[k]))
            print('  '.join(parts).rstrip(), file=out)

def format_row_align(row):
    """Format a single row in aligned [k=v] format"""
    if isinstance(row, str): return row
    parts = []
    for k in sorted(row.keys()):
        v = format_value(row[k])
        if ' ' in k or '"' in k:
            parts.append(f'["{k}"={v}]')
        else:
            parts.append(f'[{k}={v}]')
    return parts

def get_max_col_width(all_rows_parts):
    """Find max width for each column position"""
    if not all_rows_parts: return {}
    all_parts_flat = []
    for parts in all_rows_parts:
        all_parts_flat.extend(parts)
    max_len = max((len(p) for p in all_parts_flat), default=0)
    return max_len

def print_non_aggregate(rows, output_format, fmt_str=None, out=sys.stdout):
    """Print non-aggregate rows"""
    # Collect all parts to determine column widths
    all_row_parts = []
    for row in rows:
        if output_format == 'json':
            print(format_row_json(row), file=out)
        elif output_format == 'logfmt':
            print(format_row_logfmt(row), file=out)
        elif output_format == 'format' and fmt_str:
            print(format_row_fmt(row, fmt_str), file=out)
        else:  # legacy or default
            if isinstance(row, str):
                print(row, file=out)
            else:
                parts = format_row_align(row)
                all_row_parts.append(parts)

    if all_row_parts and output_format not in ('json','logfmt','format'):
        # Find max width per column
        max_cols = max(len(p) for p in all_row_parts)
        col_widths = [0] * max_cols
        for parts in all_row_parts:
            for i, p in enumerate(parts):
                col_widths[i] = max(col_widths[i], len(p))
        for parts in all_row_parts:
            formatted = []
            for i, p in enumerate(parts):
                w = col_widths[i] if i < len(col_widths) else len(p)
                formatted.append(p.ljust(w))
            print('  '.join(formatted).rstrip(), file=out)


# ===================== ALIAS LOADING =====================

def load_aliases(alias_dirs, no_alias=False):
    if no_alias: return {}
    aliases = {}
    for d in alias_dirs:
        if not os.path.isdir(d): continue
        try:
            for fname in os.listdir(d):
                fpath = os.path.join(d, fname)
                if os.path.isfile(fpath):
                    try:
                        with open(fpath) as f:
                            content = f.read()
                        # Parse TOML-like: keyword = "..." template = """..."""
                        alias = parse_alias_toml(content)
                        if alias and 'keyword' in alias and 'template' in alias:
                            aliases[alias['keyword']] = alias['template'].strip()
                    except Exception as e:
                        print(f"warning: invalid alias: {e}\n--> {fpath}\n |\n |", file=sys.stderr)
        except: pass
    return aliases

def parse_alias_toml(content):
    """Very simple TOML parser for alias files"""
    result = {}
    # Handle multiline strings
    lines = content
    # keyword = "value"
    m = re.search(r'keyword\s*=\s*"([^"]*)"', lines)
    if m: result['keyword'] = m.group(1)
    # template = """..."""
    m = re.search(r'template\s*=\s*"""(.*?)"""', lines, re.DOTALL)
    if m: result['template'] = m.group(1)
    else:
        m = re.search(r'template\s*=\s*"([^"]*)"', lines)
        if m: result['template'] = m.group(1)
    return result

def find_alias_dirs(base, alias_dir_arg=None):
    if alias_dir_arg:
        return [alias_dir_arg]
    dirs = []
    d = os.path.abspath(base)
    for _ in range(20):
        candidate = os.path.join(d, '.agrind-aliases')
        if os.path.isdir(candidate):
            dirs.append(candidate)
        parent = os.path.dirname(d)
        if parent == d: break
        d = parent
    return dirs


# ===================== MAIN =====================

def main():
    parser = argparse.ArgumentParser(prog='ag', add_help=False)
    parser.add_argument('query', nargs='?', default=None)
    parser.add_argument('-f', '--file', default=None)
    parser.add_argument('-m', '--format', default=None, dest='fmt_deprecated')
    parser.add_argument('-o', '--output', default=None)
    parser.add_argument('-a', '--alias-dir', default=None)
    parser.add_argument('--no-alias', action='store_true')
    parser.add_argument('-h', '--help', action='store_true')
    parser.add_argument('-V', '--version', action='store_true')

    args, _ = parser.parse_known_args()

    if args.version:
        print("ag 0.19.6"); return

    if args.help:
        print("""Usage: executable [OPTIONS] [QUERY]

Arguments:
  [QUERY]
          The query

Options:
  -f, --file <FILE>
          Optionally reads from a file instead of Stdin

  -m, --format <FORMAT>
          DEPRECATED. Use -o format=... instead. Provide a Rust std::fmt string to format output

  -o, --output <OUTPUT>
          Set output format. Options: 
          - `json`,
          - `logfmt`
          - `format=<rust format string>` (eg. -o format='{src} => {dst}'
          - `legacy` The original output format, auto aligning [k=v]

  -a, --alias-dir <ALIAS_DIR>
          Specifies an alternative directory to use for aliases. Defaults to `.agrind-aliases` in all parent directories.

      --no-alias
          Disables aliases

  -h, --help
          Print help (see a summary with '-h')

  -V, --version
          Print version

For more details + docs, see https://github.com/rcoh/angle-grinder""")
        return

    if args.query is None:
        print("Error: MissingQuery")
        sys.exit(1)

    # Determine output format
    output_format = 'legacy'
    fmt_str = None
    out_arg = args.output or args.fmt_deprecated
    if out_arg:
        if out_arg == 'json': output_format = 'json'
        elif out_arg == 'logfmt': output_format = 'logfmt'
        elif out_arg == 'legacy': output_format = 'legacy'
        elif out_arg.startswith('format='):
            output_format = 'format'
            fmt_str = out_arg[7:]
        else:
            output_format = 'format'
            fmt_str = out_arg

    # Load aliases
    alias_dirs = find_alias_dirs(os.getcwd(), args.alias_dir)
    aliases = load_aliases(alias_dirs, args.no_alias)

    # Parse query
    try:
        qparser = Parser(args.query, aliases)
        filt, ops = qparser.parse()
    except ParseError as e:
        print(e.format(), file=sys.stderr)
        print("Error: Failed to parse query", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

    # Read input
    if args.file:
        try:
            infile = open(args.file)
        except Exception as e:
            print(f"Error: {e}", file=sys.stderr)
            sys.exit(1)
    else:
        infile = sys.stdin

    is_tty = sys.stdout.isatty()

    # Process lines through filter
    lines = []
    try:
        for line in infile:
            line = line.rstrip('\n')
            if apply_filter(line, filt):
                lines.append(line)
    finally:
        if args.file and infile != sys.stdin:
            infile.close()

    # Build rows (start as raw strings)
    rows = lines

    # Apply operators
    is_aggregate = False
    for op in ops:
        rows, is_aggregate, _ = run_op(op, rows, is_tty)

    # Output
    if is_aggregate:
        if output_format == 'json':
            for row in rows:
                print(format_row_json(row))
        elif output_format == 'logfmt':
            for row in rows:
                print(format_row_logfmt(row))
        elif output_format == 'format' and fmt_str:
            for row in rows:
                print(format_row_fmt(row, fmt_str))
        else:
            print_aggregate_table(rows)
    else:
        print_non_aggregate(rows, output_format, fmt_str)


if __name__ == '__main__':
    main()
