        if c == '|': toks.append(Tok('PIPE','|',i)); i+=1; continue
        if c == ',': toks.append(Tok('COMMA',',',i)); i+=1; continue
        if c == '(': toks.append(Tok('LP','(',i)); i+=1; continue
        if c == ')': toks.append(Tok('RP',')',i)); i+=1; continue
        if c == '+': toks.append(Tok('PLUS','+',i)); i+=1; continue
        if c == '/': toks.append(Tok('DIV','/',i)); i+=1; continue
        if c == '%': toks.append(Tok('MOD','%',i)); i+=1; continue
        if c == '.': toks.append(Tok('DOT','.',i)); i+=1; continue
        if c == '-': toks.append(Tok('MINUS','-',i)); i+=1; continue
        if c == '*': toks.append(Tok('STAR','*',i)); i+=1; continue
        if text[i:i+2] in ('==','!=','>=','<='): toks.append(Tok('OP',text[i:i+2],i)); i+=2; continue
        if c in '<>': toks.append(Tok('OP',c,i)); i+=1; continue
