# Column width tracking with threshold=5 mechanism

class ColWidthTracker:
    """Tracks column widths with threshold=5 update rule"""
    def __init__(self):
        self.widths = []  # per column index: current max width

    def get_width(self, col_idx):
        if col_idx >= len(self.widths): return 0
        return self.widths[col_idx]

    def update(self, col_idx, new_width):
        """Update if new_width - current >= 5"""
        while col_idx >= len(self.widths): self.widths.append(0)
        if new_width - self.widths[col_idx] >= 5:
            self.widths[col_idx] = new_width
            return True
        return False

def col_formula(key, val_str):
    """Compute column 'advance' amount: 2*key_len + val_len + 10"""
    return 2*len(key) + len(val_str) + 10

class NonAggRenderer:
    """Renders non-aggregate rows with column alignment"""
    def __init__(self, output_format='legacy', fmt_str=None):
        self.output_format = output_format
        self.fmt_str = fmt_str
        # Global sorted key list with last formula per key
        self.global_keys = []  # list of keys in sorted order
        self.key_formula = {}  # key -> last formula

    def _find_insert_pos(self, key):
        """Find the insertion position in global_keys for a new key"""
        lo, hi = 0, len(self.global_keys)
        while lo < hi:
            mid = (lo+hi)//2
            if self.global_keys[mid] < key: lo = mid+1
            else: hi = mid
        return lo

    def render(self, row):
        if isinstance(row, str):
            print(row)
            return

        if self.output_format == 'json':
            print(self._fmt_json(row)); return
        if self.output_format == 'logfmt':
            print(self._fmt_logfmt(row)); return
        if self.output_format == 'format' and self.fmt_str:
            print(self._fmt_format(row)); return

        # Legacy format with column alignment
        sorted_keys = sorted(row.keys())

        # Insert new keys into global list
        for k in sorted_keys:
            if k not in self.key_formula:
                pos = self._find_insert_pos(k)
                self.global_keys.insert(pos, k)
                # Initialize formula to 0 (will be set on first render)
                self.key_formula[k] = 0

        # Compute rendering positions by iterating global keys
        positions = {}
        cursor = 0
        for k in self.global_keys:
            if k in row:
                positions[k] = cursor
            # Advance cursor by this key's formula (whether or not in row)
            formula = self.key_formula[k]
            cursor += formula

        # Render the row
        parts = []
        for k in sorted_keys:
            v = row[k]
            vs = format_value(v)
            fld = f"[{k}={vs}]"
            parts.append((positions[k], fld))

        # Build output line with proper spacing
        line = ''
        for start, fld in parts:
            while len(line) < start:
                line += ' '
            line += fld
        print(line.rstrip())

        # Update formulas AFTER rendering (with threshold=5)
        for k in sorted_keys:
            v = row[k]
            vs = format_value(v)
            new_formula = col_formula(k, vs)
            old_formula = self.key_formula[k]
            if new_formula - old_formula >= 5 or old_formula == 0:
                self.key_formula[k] = new_formula

    def _fmt_json(self, row):
        def to_j(v):
            if isinstance(v, dict): return {k: to_j(vv) for k,vv in v.items()}
            if isinstance(v, list): return [to_j(x) for x in v]
            return v
        return json.dumps({k: to_j(v) for k,v in sorted(row.items())})

    def _fmt_logfmt(self, row):
        parts = []
        for k in sorted(row.keys()):
            v = format_value(row[k])
            if ' ' in v or '=' in v or '"' in v: v = '"' + v.replace('"','\\"') + '"'
            parts.append(f'{k}={v}')
        return ' '.join(parts)

    def _fmt_format(self, row):
        result = self.fmt_str
        for k,v in row.items():
            result = result.replace('{'+k+'}', format_value(v))
        return result


class AggRenderer:
    """Renders aggregate table output"""
    def __init__(self, output_format='legacy', fmt_str=None):
        self.output_format = output_format
        self.fmt_str = fmt_str
        self.col_widths = {}  # col_name -> current width
        self.col_order = []  # order of columns
        self.rows_buf = []  # buffered rows for final output
        self.header_printed = False

    def _init_cols(self, row):
        for k in row.keys():
            if k not in self.col_widths:
                self.col_order.append(k)
                self.col_widths[k] = len(str(k))  # start with header width

    def process_row(self, row):
        if isinstance(row, str): return
        self._init_cols(row)
        # Update column widths
        for k,v in row.items():
            if k not in self.col_widths:
                self.col_order.append(k)
                self.col_widths[k] = len(str(k))
            vs = format_value(v)
            new_w = len(vs)
            old_w = self.col_widths[k]
            if new_w - old_w >= 5:
                self.col_widths[k] = new_w
        self.rows_buf.append(row)

    def finalize(self):
        if not self.rows_buf:
            print("No data"); return

        if self.output_format == 'json':
            for row in self.rows_buf:
                def to_j(v):
                    if isinstance(v,dict): return {k:to_j(vv) for k,vv in v.items()}
                    if isinstance(v,list): return [to_j(x) for x in v]
                    return v
                print(json.dumps({k:to_j(v) for k,v in sorted(row.items())}))
            return

        if self.output_format == 'logfmt':
            for row in self.rows_buf:
                parts=[]
                for k in sorted(row.keys()):
                    v=format_value(row[k])
                    if ' ' in v or '=' in v or '"' in v: v='"'+v.replace('"','\\"')+'"'
                    parts.append(f'{k}={v}')
                print(' '.join(parts))
            return

        if self.output_format == 'format' and self.fmt_str:
            for row in self.rows_buf:
                result=self.fmt_str
                for k,v in row.items(): result=result.replace('{'+k+'}',format_value(v))
                print(result)
            return

        # Table format
        # Final column widths: max(header, max_val_seen)
        final_widths = {}
        for k in self.col_order:
            final_widths[k] = self.col_widths[k]

        # Print header
        header = '  '.join(k.ljust(final_widths[k]) for k in self.col_order)
        sep = '-' * (sum(final_widths[k]+2 for k in self.col_order) - 2 + 2)
        print(header.rstrip())
        print(sep)
        for row in self.rows_buf:
            parts = []
            for k in self.col_order:
