    except: return None

def parse_logfmt_str(s):
    result={}; i=0
    while i<len(s):
        while i<len(s) and s[i]==' ': i+=1
        if i>=len(s): break
        ks=i
        while i<len(s) and s[i] not in ('=',' '): i+=1
        key=s[ks:i]
        if not key: i+=1; continue
        if i>=len(s) or s[i]!='=': result[key]=''; continue
        i+=1
        if i<len(s) and s[i]=='"':
            i+=1; vp=[]
            while i<len(s) and s[i]!='"':
                if s[i]=='\\' and i+1<len(s): vp.append(s[i+1]); i+=2
                else: vp.append(s[i]); i+=1
            result[key]=''.join(vp)
            if i<len(s): i+=1
        else:
            vs=i
            while i<len(s) and s[i]!=' ': i+=1
            result[key]=s[vs:i]
    return result

def pattern_to_regex(pattern):
    parts=pattern.split('*')
    if len(parts)==1: return re.compile(re.escape(pattern),re.IGNORECASE)
    segs=[]
    for i,p in enumerate(parts):
        segs.append(re.escape(p))
        if i<len(parts)-1: segs.append('(.*?)')
    regex=''.join(segs)
    if parts[-1]=='': regex=regex[:-len('(.*?)')]+r'(.*)'
    return re.compile(regex,re.IGNORECASE|re.DOTALL)

