            ot=op[0]
            if ot=='count': s[op[2] or '_count']=0
            elif ot=='sum': s[op[2] or '_sum']=0.0
            elif ot in ('min','max'): s[op[2] or '_'+ot]=None
            elif ot=='average': s[op[2] or '_average']=[0.0,0]
            elif ot=='count_distinct': s[op[2] or '_countDistinct']=set()
            elif ot=='percentile': s[op[3] or f'p{op[1]}']=[]
