# For strings in desc order: I need to negate somehow. 
# Can't negate strings directly, but can reverse with a key that sorts in reverse.
# One approach: use a custom comparison that reverses string comparison.

# For desc sort of strings: the comparison should be reversed.
# Option: return (0, -ord-based-hash)? Too complex.
# Better: separate the handling - for strings in desc, use a wrapper that reverses.

# Actually, the simplest approach: sort in ascending order first, then reverse for the key.
# But we have mixed asc/desc keys.

# For string desc: use (-1, string) and compare tuples where (-1, 'z') < (-1, 'a') because 'z' > 'a'?
# No that doesn't work with Python tuple comparison for mixed types.

# Best approach: use a key function that returns a ReverseStr wrapper for desc strings:

python3 << 'EOF'
content = open('agrind_py/agrind.py').read()

old_sort_kfn = """    if ot=='sort':
        sk=op[1]
        def kfn(row):
            if isinstance(row,str): return [(1,'')]
            k=[]
            for expr,direction in sk:
                v=eval_sort_key(expr,row)
                if direction=='desc':
                    if v[0]==0: k.append((0,-v[1]))
                    else: k.append((2,v[1]))
                else: k.append(v)
            return k"""

new_sort_kfn = """    if ot=='sort':
        sk=op[1]
        def kfn(row):
            if isinstance(row,str): return [(1, 0, '')]
            k=[]
            for expr,direction in sk:
                v=eval_sort_key(expr,row)
                if direction=='desc':
                    if v[0]==0: k.append((0, -v[1], ''))  # numeric desc
                    else: k.append((2, 0, ''.join(chr(0x10FFFF - ord(c)) if ord(c) <= 0x10FFFF else c for c in v[1])))
                else:
                    if v[0]==0: k.append((0, v[1], ''))
                    else: k.append((2, 0, v[1]))
            return k"""

content = content.replace(old_sort_kfn, new_sort_kfn)
open('agrind_py/agrind.py', 'w').write(content)
print("Fixed sort key for strings")
EOF

